  if (trimmed === '*') return [];

  const tokens = trimmed.split(/ +/);
  const comparators = [];
  const OP_PATTERN = /^(>=|<=|>|<|=)(.+)$/;

  for (const token of tokens) {
    if (token === '*') throw new ResolveError('BAD_RANGE', `invalid range: ${text}`);

    let operator;
    let versionText;

    if (token.startsWith('^')) {
      versionText = token.slice(1);
      let version;
      try {
        version = parseVersion(versionText);
      } catch {
        throw new ResolveError('BAD_RANGE', `invalid range: ${text}`);
      }
      let upper;
      if (version.major !== 0) {
        upper = `${version.major + 1}.0.0`;
      } else if (version.minor !== 0) {
        upper = `0.${version.minor + 1}.0`;
      } else {
        upper = `0.0.${version.patch + 1}`;
      }
      comparators.push({ operator: '>=', version: versionText });
      comparators.push({ operator: '<', version: upper });
      continue;
    }

    if (token.startsWith('~')) {
      versionText = token.slice(1);
      let version;
      try {
        version = parseVersion(versionText);
      } catch {
        throw new ResolveError('BAD_RANGE', `invalid range: ${text}`);
      }
      const upper = `${version.major}.${version.minor + 1}.0`;
      comparators.push({ operator: '>=', version: versionText });
      comparators.push({ operator: '<', version: upper });
      continue;
    }

    const match = OP_PATTERN.exec(token);
    if (match !== null) {
      operator = match[1];
      versionText = match[2];
    } else {
      operator = '=';
      versionText = token;
    }

    try {
      parseVersion(versionText);
    } catch {
      throw new ResolveError('BAD_RANGE', `invalid range: ${text}`);
    }
    comparators.push({ operator, version: versionText });
  }

  return comparators;
}

/**
 * Test a version against a range.
 *
 * @param {string} version Version to test.
 * @param {string} range Range to test against.
 * @returns {boolean} True when every comparator holds.
 */
export function satisfies(version, range) {
  parseVersion(version);
  const comparators = parseRange(range);
  for (const { operator, version: bound } of comparators) {
    const cmp = compareVersions(version, bound);
    if (operator === '>=' && !(cmp >= 0)) return false;
    if (operator === '<=' && !(cmp <= 0)) return false;
    if (operator === '>' && !(cmp > 0)) return false;
    if (operator === '<' && !(cmp < 0)) return false;
    if (operator === '=' && !(cmp === 0)) return false;
  }
  return true;
}

/**
 * Highest version of a list that satisfies a range.
 *
 * @param {string[]} versions Candidate versions.
 * @param {string} range Range to satisfy.
 * @returns {string|null} The highest match, or null.
